<script setup>import {ref,reactive,onMounted} from 'vue';import {useRouter} from 'vue-router';import {api,money,toast} from '../core';const router=useRouter(),addresses=ref([]),addressId=ref(''),quote=ref(null),busy=ref(false),error=ref(''),operationId=ref(crypto.randomUUID()),editing=ref(null),form=reactive({recipient:'',phone:'',address:''});async function load(){try{addresses.value=await api('/addresses');if(!addressId.value&&addresses.value.length)addressId.value=addresses.value[0].id;if(addressId.value)await refresh()}catch(e){error.value=e.message}}async function refresh(){quote.value=null;error.value='';operationId.value=crypto.randomUUID();try{quote.value=await api('/orders/quote?addressId='+addressId.value)}catch(e){error.value=e.message}}function edit(a){editing.value=a?.id||null;form.recipient=a?.recipient||'';form.phone=a?.phone||'';form.address=a?.address||''}async function save(){busy.value=true;try{const body={...form};if(editing.value)body.version=addresses.value.find(a=>a.id===editing.value).version;const a=await api('/addresses'+(editing.value?'/'+editing.value:''),editing.value?'PUT':'POST',body);addressId.value=a.id;edit(null);await load();toast('收货地址已保存')}catch(e){toast(e.message,true)}finally{busy.value=false}}async function submit(){busy.value=true;error.value='';try{await api('/orders','POST',{addressId:addressId.value,quoteToken:quote.value.quoteToken,operationId:operationId.value});toast('订单已创建，请在订单页模拟付款');router.push('/orders')}catch(e){error.value=e.message;if(e.status===409)quote.value=null}finally{busy.value=false}}onMounted(load);</script><template><section class="shell section"><p class="eyebrow">ONE STEP CLOSER</p><h1>确认这份心意</h1><div class="cart-layout"><div><div class="panel"><h3>收货信息</h3><label v-for="a in addresses" :key="a.id" class="address-choice"><input type="radio" v-model="addressId" :value="a.id" @change="refresh"><span><strong>{{a.recipient}} · {{a.phone}}</strong><small>{{a.address}}</small></span><button class="text-button" @click.prevent="edit(a)">编辑</button></label><h4>{{editing?'编辑地址':'添加收货地址'}}</h4><form class="form-stack" @submit.prevent="save"><div class="form-grid"><label>收件人<input v-model="form.recipient" required maxlength="50"></label><label>联系电话<input v-model="form.phone" required maxlength="32"></label></div><label>详细地址<textarea v-model="form.address" required maxlength="300" rows="2"></textarea></label><button class="btn secondary small" :disabled="busy">保存地址</button></form></div><div v-if="quote" class="panel mt"><h3>已选商品</h3><div v-for="i in quote.items" :key="i.productId" class="row between order-line"><span>{{i.name}} × {{i.quantity}}</span><strong>¥{{money(i.price*i.quantity)}}</strong></div></div></div><aside class="panel summary"><h3>订单金额</h3><template v-if="quote"><div class="row between"><span>商品总额</span><span>¥{{money(quote.subtotal)}}</span></div><div class="row between"><span>满减优惠</span><span>− ¥{{money(quote.discount)}}</span></div><div class="row between"><span>八折模拟优惠</span><span>− ¥{{money(quote.subsidy)}}</span></div><hr><div class="row between"><strong>应付金额</strong><strong class="price">¥{{money(quote.payable)}}</strong></div></template><p v-else class="muted">选择地址后核对最新报价</p><p class="hint">满300减30 / 满600减80 / 满1500减300，取最高档后再八折。不涉及真实政府补贴。</p><p v-if="error" class="error" role="alert">{{error}}</p><button v-if="!quote&&addressId" class="btn secondary wide" :disabled="busy" @click="refresh">重新获取报价</button><button class="btn wide" :disabled="busy||!quote" @click="submit">{{busy?'正在提交…':'确认并提交订单'}}</button><p class="hint">未确认结果时，先核对我的订单；本次重试沿用原操作标识。</p></aside></div></section></template>
